// Brother QL media and models (data in MediaTable.g.cs, generated by driver/gen/media.py).
using System;
using System.Globalization;
using System.Linq;

namespace QlLabels
{
    enum MediaKind { Continuous, DieCut, Round }

    sealed class Media
    {
        public readonly int Id;
        public readonly string Name;
        public readonly MediaKind Kind;
        public readonly int Width01, Length01;           // 0.1 mm; Length01 = 0 for continuous
        public readonly int PageWidthUm, PageLengthUm;   // the driver's page size (0.001 mm)
        public readonly int TopDots;                     // top offset at 300 dpi (continuous: default feed)
        public readonly int MinLength01, MaxLength01, DefaultLength01;  // continuous only
        public readonly int PrintDots;                   // printable width at 300 dpi (the print head's band on this paper)

        public Media(int id, string name, MediaKind kind, int width01, int length01, int pageWidthUm, int pageLengthUm,
                     int topDots, int minLength01, int maxLength01, int defaultLength01, int printDots)
        {
            PrintDots = printDots;
            Id = id; Name = name; Kind = kind; Width01 = width01; Length01 = length01;
            PageWidthUm = pageWidthUm; PageLengthUm = pageLengthUm; TopDots = topDots;
            MinLength01 = minLength01; MaxLength01 = maxLength01; DefaultLength01 = defaultLength01;
        }

        public bool Continuous { get { return Kind == MediaKind.Continuous; } }
        public double WidthMm { get { return Width01 / 10.0; } }
        public double LengthMm { get { return Length01 / 10.0; } }
        public double TopMm { get { return TopDots * 25.4 / 300; } }

        public string KindText
        {
            get { return Kind == MediaKind.Continuous ? Lang.T("continuous") : Kind == MediaKind.Round ? Lang.T("round") : Lang.T("die-cut"); }
        }

        // "62 mm continuous", "29 × 90 mm die-cut", "Ø 12 mm round"
        public string Display
        {
            get
            {
                if (Kind == MediaKind.Continuous) return Lang.F("{0} mm continuous", Mm(WidthMm));
                if (Kind == MediaKind.Round) return Lang.F("Ø {0} mm round", Mm(WidthMm));
                return Lang.F("{0} × {1} mm die-cut", Mm(WidthMm), Mm(LengthMm));
            }
        }

        public override string ToString() { return Display; }

        public static string Mm(double v) { return v.ToString("0.##", CultureInfo.CurrentCulture); }
    }

    // A printer model of the driver package (list in MediaTable.g.cs, generated from MODELS in driver/gen/media.py).
    sealed class QlModel
    {
        public readonly string Name;        // "QL-800"
        public readonly string DriverName;  // "Brother QL-800 (Unidrv)"
        public readonly int StatusCode;     // byte 4 of the status reply
        public readonly bool TwoColor;      // prints black and red on DK-22251 (62 mm continuous)
        public readonly int MinLength01;    // shortest continuous label (QL-500/550/560/650TD: 25 mm)
        public readonly int MaxLength01;    // longest continuous label: the GPD's custom-size maximum (1 m; wide models 3 m)
        readonly int[] paperIds;

        public QlModel(string name, string driverName, int statusCode, bool twoColor, int minLength01, int maxLength01, int[] paperIds)
        {
            Name = name; DriverName = driverName; StatusCode = statusCode; TwoColor = twoColor; MinLength01 = minLength01; MaxLength01 = maxLength01;
            this.paperIds = paperIds;
        }

        public bool HasPaper(int id) { return Array.IndexOf(paperIds, id) >= 0; }

        public static QlModel ForDriver(string driverName)
        {
            if (driverName == null) return null;
            return MediaTable.Models.FirstOrDefault(m => string.Equals(m.DriverName, driverName, StringComparison.OrdinalIgnoreCase));
        }

        public static QlModel ForStatusCode(int code) { return MediaTable.Models.FirstOrDefault(m => m.StatusCode == code); }

        // Name for a status model code: "QL-500/550" where models share one (their replies are the same).
        public static string NameForStatusCode(int code)
        {
            var names = MediaTable.Models.Where(m => m.StatusCode == code).Select(m => m.Name).OrderBy(n => n, StringComparer.Ordinal).ToList();
            if (names.Count == 0) return null;
            return names[0] + string.Concat(names.Skip(1).Select(n => "/" + (n.StartsWith("QL-") ? n.Substring(3) : n)));
        }

        public static string[] DriverNames
        {
            get { return MediaTable.Models.Select(m => m.DriverName).ToArray(); }
        }

        // "QL-500/550/.../1115NWB" (the model list, sorted by model number)
        public static string AllNames
        {
            get
            {
                var names = MediaTable.Models.Select(m => m.Name).ToList();
                return names[0] + string.Concat(names.Skip(1).Select(n => "/" + (n.StartsWith("QL-") ? n.Substring(3) : n)));
            }
        }

        public override string ToString() { return Name; }
    }

    static partial class MediaTable
    {
        public static Media ById(int id) { return All.FirstOrDefault(m => m.Id == id); }

        // Continuous rolls by width, then die-cut labels, then round labels.
        public static Media[] Ordered()
        {
            return All.OrderBy(m => m.Kind == MediaKind.Continuous ? 0 : m.Kind == MediaKind.DieCut ? 1 : 2)
                      .ThenBy(m => m.Width01).ThenBy(m => m.Length01).ToArray();
        }

        public static bool IsMediaName(string name)
        {
            return All.Any(m => string.Equals(m.Name, name, StringComparison.OrdinalIgnoreCase)) ||
                   MultiUpNames.Contains(name, StringComparer.OrdinalIgnoreCase);
        }
    }
}
